def breaking(contract, response):
    types = {'str': str, 'int': int, 'float': float, 'bool': bool, 'list': list, 'dict': dict}
    out = []
    for field, tname in contract.items():
        if field not in response:
            out.append(f'{field}: missing')
            continue
        v = response[field]
        ok = isinstance(v, types[tname])
        if tname == 'int' and isinstance(v, bool):
            ok = False
        if not ok:
            out.append(f'{field}: expected {tname}')
    return sorted(out)
